import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';
import { MAX_SNAPSHOT_BYTES, normalizeSnapshot, normalizeProgress, normalizeRoomOverrides, parseGameLink, suggestedStage } from '../src/snapshot.js';
import { applyGameProgress, defaultProfile, recommendedStage } from '../src/engine.js';
import { CAMPAIGNS } from '../src/data.js';

// Generated by the Mod's --snapshot-fixture command from fictional state only.
// Keep the actual .NET GZipStream bytes as an independent cross-runtime fixture.
const fixture = JSON.parse(readFileSync(new URL('./fixtures/mod-v2-snapshot.json', import.meta.url), 'utf8'));
const input = () => JSON.parse(fixture.json);
const progress = (fields = {}) => ({ source: 'host', scope: 'save', freshness: 'cycle-start', saveId: 'Survivor:seed:777', cycle: 12, rooms: ['SU_A01'], flags: {}, ...fields });
const packed = value => '#v=2&data=' + gzipSync(typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value)).toString('base64url');
const campaign = id => CAMPAIGNS.find(value => value.id === id);

test('actual C# gzip/base64url snapshot parses with the same data as direct JSON import', async () => {
  const result = await parseGameLink(new URL(fixture.url).hash);
  assert.deepEqual(result, normalizeSnapshot(input()));
  assert.equal(result.v, 2);
  assert.equal(result.campaign, 'survivor');
  assert.equal(result.capturedAt, '2026-10-13T12:34:56.000Z');
  assert.equal(result.progress.source, 'host');
  assert.equal(result.progress.freshness, 'cycle-start');
  assert.equal(result.route, true, 'legacy snapshots default to an enabled web-map route');
  assert.deepEqual(result.progress.rooms, ['HI_A01', 'SU_C04', 'SU_S01']);
  assert.deepEqual(result.progress.flags.ghostsTalkedTo, { CC: 2, SI: 1 });
});

test('route highlighting follows the mod snapshot toggle', () => {
  assert.equal(normalizeSnapshot({ ...input(), route: false }).route, false);
  assert.equal(normalizeSnapshot({ ...input(), route: true }).route, true);
});

test('normalization preserves local, host, and unknown remote players separately', () => {
  const { players } = normalizeSnapshot(input());
  assert.equal(players.length, 3);
  assert.equal(players[0].local, true); assert.equal(players[0].host, false);
  assert.equal(players[0].accuracy, 'pixel'); assert.equal(players[0].px, 250.5);
  assert.equal(players[1].host, true); assert.equal(players[1].local, false);
  assert.equal(players[1].accuracy, 'room'); assert.equal(players[1].room, 'HI_A01');
  assert.ok(!Object.hasOwn(players[1], 'px'));
  assert.equal(players[2].available, false); assert.ok(!Object.hasOwn(players[2], 'room'));
  assert.equal(players[2].name, '远端 <玩家>', 'names remain data for escaped rendering');
});

test('malformed player coordinates downgrade precision and never fabricate a location', () => {
  const snapshot = input();
  snapshot.players = [
    { id: 'a', name: '字'.repeat(81), available: true, accuracy: 'pixel', region: 'su', room: 'su_a01', x: 1.5, y: '2', px: NaN, py: Infinity, cx: 0, cy: 0 },
    { id: 'b', available: false, region: 'SU', room: 'SU_A01', px: 20, py: 20, cx: 0, cy: 0 },
    { id: 'c', available: true, region: '../SU', room: '<script>' },
    null, 3, [],
  ];
  const players = normalizeSnapshot(snapshot).players;
  assert.equal(players.length, 3);
  assert.equal(players[0].name.length, 80);
  assert.equal(players[0].accuracy, 'room'); assert.equal(players[0].room, 'SU_A01');
  for (const key of ['x', 'y', 'px', 'py']) assert.ok(!Object.hasOwn(players[0], key));
  for (const player of players.slice(1)) {
    assert.equal(player.available, false);
    assert.ok(!Object.hasOwn(player, 'room'));
    assert.ok(!Object.hasOwn(player, 'px'));
  }
});

test('snapshot bounds reject a 65th player but accept 64 without truncating', () => {
  const snapshot = input();
  snapshot.players = Array.from({ length: 64 }, (_, i) => ({ id: 'p' + i, available: false }));
  assert.equal(normalizeSnapshot(snapshot).players.length, 64);
  snapshot.players.push({ id: 'overflow' });
  assert.throws(() => normalizeSnapshot(snapshot), /64/);
});

test('multiplayer progress accepts only explicit host records and discards client save facts', () => {
  for (const source of ['solo', 'guest', 'client', 'unavailable', '', null]) {
    const value = normalizeProgress(progress({ source, flags: { hasMark: true }, rooms: ['SS_AI'] }), true);
    assert.equal(value.source, 'unavailable');
    assert.equal(value.saveId, ''); assert.equal(value.cycle, null);
    assert.deepEqual(value.rooms, []); assert.deepEqual(value.flags, {});
  }
  const host = normalizeProgress(progress(), true);
  assert.equal(host.source, 'host'); assert.deepEqual(host.rooms, ['SU_A01']);
  assert.equal(normalizeProgress(progress({ source: 'solo', freshness: 'live' }), false).source, 'solo');
});

test('missing or contradictory scope and freshness fail closed even with a valid source', () => {
  for (const fields of [
    { scope: undefined }, { scope: 'none' }, { scope: 'unknown' },
    { freshness: undefined }, { freshness: 'unavailable' }, { freshness: 'realtime' },
  ]) {
    const result = normalizeProgress(progress({ ...fields, flags: { hasMark: true } }), true);
    assert.equal(result.source, 'unavailable');
    assert.equal(result.scope, 'none'); assert.equal(result.freshness, 'unavailable');
    assert.deepEqual(result.rooms, []); assert.deepEqual(result.flags, {});
  }
  assert.equal(normalizeProgress(progress({ scope: 'session', freshness: 'live' }), true).source, 'host');
});

test('Meadow free mode never imports story or exploration progress even if payload claims a host save', () => {
  const snapshot = input(); snapshot.mode = 'meadow'; snapshot.avatar = 'GreenLizard';
  const result = normalizeSnapshot(snapshot);
  assert.equal(result.mode, 'meadow'); assert.equal(result.avatar, 'GreenLizard');
  assert.equal(result.progress.source, 'unavailable');
  assert.deepEqual(result.progress.rooms, []); assert.deepEqual(result.progress.flags, {});
  assert.equal(result.players.length, 3, 'player snapshots remain useful in free mode');
});

test('missing snapshot progress does not reveal any explored rooms or infer completion', () => {
  const snapshot = input(); delete snapshot.progress;
  const result = normalizeSnapshot(snapshot);
  assert.equal(result.progress.source, 'unavailable');
  assert.deepEqual(result.progress.rooms, []); assert.deepEqual(result.progress.flags, {});
  for (const value of [undefined, null, false, 3, [], 'host']) assert.equal(normalizeProgress(value), null);
});

test('explored room limit accepts 12000 and rejects overflow instead of truncating', () => {
  const rooms = Array.from({ length: 12000 }, (_, i) => 'SU_R' + i);
  assert.equal(normalizeProgress(progress({ rooms })).rooms.length, 12000);
  assert.throws(() => normalizeProgress(progress({ rooms: [...rooms, 'SU_OVER'] })), /12000/);
  assert.deepEqual(normalizeProgress(progress({ rooms: ['su_a01', 'SU_A01', '../bad', 2, null, 'HI_A02'] })).rooms, ['SU_A01', 'HI_A02']);
});

test('room overrides preserve explicit visibility only and reject oversized records', () => {
  const overrides = normalizeRoomOverrides({ su_a01: true, SU_A02: false, SU_A03: 'false', '../escape': true });
  assert.deepEqual(overrides, { SU_A01: true, SU_A02: false });
  assert.equal(Object.keys(normalizeRoomOverrides(Object.fromEntries(Array.from({ length: 12000 }, (_, i) => ['SU_' + i, true])))).length, 12000);
  assert.throws(() => normalizeRoomOverrides(Object.fromEntries(Array.from({ length: 12001 }, (_, i) => ['SU_' + i, true]))), /过大/);
});

test('only verified typed story flags survive normalization and prototype keys remain inert', () => {
  const flags = JSON.parse('{"hasMark":true,"hasRobo":"true","ascended":false,"karmaCap":9,"moonConversations":-1,"pebblesConversations":1.5,"smPearlTagged":1,"denPosition":"oe_s01","ghostsTalkedTo":{"cc":2,"SI":-1,"SL":1001,"__proto__":2},"__proto__":{"polluted":true},"extra":true}');
  const result = normalizeProgress(progress({ flags }));
  assert.deepEqual(result.flags, { hasMark: true, ascended: false, karmaCap: 9, denPosition: 'OE_S01', ghostsTalkedTo: { CC: 2 } });
  assert.equal({}.polluted, undefined);
});

test('v2 normalization rejects unsupported envelopes and invalid primary positions', () => {
  for (const value of [null, true, 'data', [], {}, { ...input(), v: 1 }, { ...input(), v: '2' }])
    assert.throws(() => normalizeSnapshot(value), /版本 2/);
  for (const fields of [{ room: '../escape' }, { region: 'SU_A' }, { x: .5 }, { px: Infinity }])
    assert.throws(() => normalizeSnapshot({ ...input(), ...fields }));
  const custom = normalizeSnapshot({ ...input(), character: 'CustomSlug' });
  assert.equal(custom.campaign, null, 'unknown characters must not silently use a different campaign');
});

test('normalization makes independent progress arrays without mutating the imported snapshot', () => {
  const snapshot = input(), before = JSON.stringify(snapshot);
  const result = normalizeSnapshot(snapshot);
  assert.equal(JSON.stringify(snapshot), before);
  snapshot.progress.rooms.push('SS_AI'); snapshot.progress.flags.ghostsTalkedTo.CC = 9;
  snapshot.players[0].name = 'changed';
  assert.ok(!result.progress.rooms.includes('SS_AI'));
  assert.equal(result.progress.flags.ghostsTalkedTo.CC, 2);
  assert.equal(result.players[0].name, '你');
});

test('game-link parser preserves v1 compatibility and ignores ordinary fragments', async () => {
  for (const hash of ['', '#', '#map', '#sync=file']) assert.equal(await parseGameLink(hash), null);
  const legacy = await parseGameLink('#v=1&character=White&region=SU&room=SU_A01');
  assert.equal(legacy.campaign, 'survivor'); assert.equal(legacy.room, 'SU_A01');
  assert.ok(!Object.hasOwn(legacy, 'progress'));
  await assert.rejects(parseGameLink('#v=3&data=abcd'), /版本/);
});

test('malformed, oversized, non-gzip and truncated compressed links are rejected', async () => {
  for (const hash of ['#v=2', '#v=2&data=', '#v=2&data=%2B%2F', '#v=2&data=' + 'A'.repeat(131073), '#v=2&data=A'])
    await assert.rejects(parseGameLink(hash));
  await assert.rejects(parseGameLink('#v=2&data=' + Buffer.from('not gzip').toString('base64url')));
  const bytes = gzipSync(JSON.stringify(input()));
  await assert.rejects(parseGameLink('#v=2&data=' + bytes.subarray(0, bytes.length - 7).toString('base64url')));
});

test('gzip expansion limit stops bombs beyond 1 MiB while the exact limit remains valid', async () => {
  const base = JSON.stringify(input()), bytes = Buffer.byteLength(base);
  const exact = base + ' '.repeat(MAX_SNAPSHOT_BYTES - bytes);
  assert.equal(Buffer.byteLength(exact), MAX_SNAPSHOT_BYTES);
  assert.equal((await parseGameLink(packed(exact))).room, 'SU_C04');
  await assert.rejects(parseGameLink(packed(exact + ' ')), /1 MB/);
});

test('compressed invalid UTF-8 and non-JSON payloads are rejected after decompression', async () => {
  await assert.rejects(parseGameLink(packed(Buffer.from([0xff, 0xfe, 0xff]))));
  await assert.rejects(parseGameLink(packed('{')));
  await assert.rejects(parseGameLink(packed('null')), /版本 2/);
});

test('same-save snapshots replace authoritative rooms and flags instead of accumulating history', () => {
  const profile = defaultProfile(campaign('survivor'));
  profile.gameProgress = normalizeProgress(progress({ rooms: ['SU_A01', 'SS_AI'], flags: { hasMark: true } }));
  profile.roomOverrides = { SU_A01: false, HI_A01: true }; profile.completed = ['first-visit']; profile.hint = 2;
  const next = normalizeProgress(progress({ rooms: ['SU_A01'], flags: { hasMark: false }, cycle: 2 }));
  assert.equal(applyGameProgress(profile, next), false);
  assert.deepEqual(profile.gameProgress.rooms, ['SU_A01']);
  assert.equal(profile.gameProgress.flags.hasMark, false);
  assert.deepEqual(profile.roomOverrides, { SU_A01: false, HI_A01: true });
  assert.deepEqual(profile.completed, ['first-visit']); assert.equal(profile.hint, 2);
});

test('switching save identity or provenance clears manual visibility and completed story markers', () => {
  for (const next of [progress({ saveId: 'Survivor:seed:888' }), progress({ source: 'solo', freshness: 'live' }), progress({ saveId: '' })]) {
    const profile = defaultProfile(campaign('survivor'));
    profile.gameProgress = normalizeProgress(progress()); profile.roomOverrides = { SS_AI: true };
    profile.completed = ['first-visit']; profile.hint = 2; profile.notes = '保留笔记';
    assert.equal(applyGameProgress(profile, normalizeProgress(next)), true);
    assert.deepEqual(profile.roomOverrides, {}); assert.deepEqual(profile.completed, []);
    assert.equal(profile.hint, 0); assert.equal(profile.notes, '保留笔记');
  }
});

test('unavailable progress replaces prior host exploration without retaining revealed rooms', () => {
  const profile = defaultProfile(campaign('survivor'));
  profile.gameProgress = normalizeProgress(progress()); profile.roomOverrides = { SS_AI: true };
  const unknown = normalizeProgress(progress({ source: 'unavailable' }));
  assert.equal(applyGameProgress(profile, unknown), true);
  assert.equal(profile.gameProgress.source, 'unavailable');
  assert.deepEqual(profile.gameProgress.rooms, []); assert.deepEqual(profile.roomOverrides, {});
});

test('recommendations rely on actual flags, not mere visits or conversation-start counts', () => {
  const seen = normalizeProgress(progress({ rooms: ['SS_AI', 'LC_A01', 'OE_FINAL'], flags: { pebblesConversations: 1 } }));
  assert.equal(suggestedStage('gourmand', seen), null);
  assert.equal(suggestedStage('artificer', seen), null);
  assert.equal(suggestedStage('gourmand', { ...seen, flags: { hasMark: true } }), 'gourmand-west');
  assert.equal(suggestedStage('artificer', { ...seen, flags: { hasRobo: true } }), null);
  assert.equal(suggestedStage('artificer', { ...seen, flags: { hasRobo: true, hasMark: true } }), 'artificer-city');
  assert.equal(suggestedStage('watcher', seen), null, 'no invented Watcher completion');
  assert.equal(suggestedStage('survivor', normalizeProgress(progress({ source: 'unavailable', flags: { hasMark: true } }))), null);
});

test('recommended stage advances past completed suggestions and never falls back to earlier unfinished goals', () => {
  const c = campaign('survivor'), profile = defaultProfile(c);
  profile.gameProgress = normalizeProgress(progress({ flags: { moonConversations: 1 } }));
  assert.equal(recommendedStage(c, profile).id, 'high-visit');
  profile.completed = ['high-visit'];
  assert.equal(recommendedStage(c, profile).id, 'far-journey');
  profile.completed.push('far-journey');
  assert.equal(recommendedStage(c, profile), null, 'does not return to earlier first-visit objective');
  assert.ok(!profile.completed.includes('first-visit'), 'recommendations do not write completion marks');
});

test('Saint echo facts and Rivulet progression use exact observed state', () => {
  const p = flags => normalizeProgress(progress({ flags }));
  assert.equal(suggestedStage('saint', p({ ghostsTalkedTo: { SI: 2, CC: 1 } })), 'saint-two');
  assert.equal(suggestedStage('saint', p({ karmaCap: 9 })), 'saint-close');
  assert.equal(suggestedStage('rivulet', p({ pebblesConversations: 1 })), 'rivulet-carry');
  assert.equal(suggestedStage('rivulet', p({ pebblesEnergyTaken: true })), 'rivulet-deep');
  assert.equal(suggestedStage('rivulet', p({ moonHeartRestored: true, pebblesEnergyTaken: true })), 'rivulet-return');
  assert.equal(suggestedStage('spearmaster', p({ smPearlTagged: true })), 'spear-final');
});
